commit 5f9b246fd01e90afa8075c1b6c2904ea44375fe3
Author: Martin Mitáš <mity@morous.org>
Date:   Tue May 12 20:57:46 2026 +0200

    md_process_line: Fix admonition handling.

     * We could have incorrectly remember old pivot_line corresponding to the
       previously processed block when detecting the admonition.

     * Also make sure we match all admonition tag, not just its prefix.

    Fixes #320.

diff --git a/src/md4c.c b/src/md4c.c
index 9f11742..4641375 100644
--- a/src/md4c.c
+++ b/src/md4c.c
@@ -6561,10 +6561,13 @@ md_process_line(MD_CTX* ctx, const MD_LINE_ANALYSIS** p_pivot_line, MD_LINE_ANAL
             unsigned i;

             for(i = 0; i < SIZEOF_ARRAY(MD_ADMONITION_TAGS); i++) {
-                if(md_ascii_case_eq(STR(line->beg+2), MD_ADMONITION_TAGS[i], md_strlen(MD_ADMONITION_TAGS[i]))) {
+                if(line->end - line->beg == md_strlen(MD_ADMONITION_TAGS[i]) + 3  &&
+                   md_ascii_case_eq(STR(line->beg+2), MD_ADMONITION_TAGS[i], line->end - line->beg - 3))
+                {
                     ctx->containers[ctx->n_containers-1].is_admonition = TRUE;
                     block->type = MD_BLOCK_ADMONITION;
                     block->data = i;
+                    *p_pivot_line = &md_dummy_blank_line;
                     return 0;
                 }
             }
